// Des: Command probe: save redacted Zalo page dump for labels
// Flo: open browser > AX snapshot + page text > redact by registry > write <stat>/probe/<name>.json > print counts
// I/O: Ctx + name (caller) > redacted json file, stdout line; exit 0
// ===================================================================
const std = @import("std"); const ctxz = @import("ct-ctrl-ctxz.zig"); const snap = @import("ru-page-snap.zig"); const prob = @import("ru-page-prob.zig"); const lab = @import("cf-labl-load.zig"); const file = @import("st-stor-file.zig");
pub fn nameOk(name: []const u8) bool { if (name.len == 0 or name.len > 40) return false; for (name) |chr| { if (!(std.ascii.isLower(chr) or std.ascii.isDigit(chr) or chr == '-' or chr == '_')) return false; } return true; }
const SKEL = "(function(){var m={};document.querySelectorAll('body *').forEach(function(e){var k=e.tagName.toLowerCase();if(e.id&&!/\\d{4}/.test(e.id))k+='#'+e.id;e.classList.forEach(function(c){k+='.'+c});for(var i=0;i<e.attributes.length;i++){var n=e.attributes[i].name;if(n.indexOf('data-')===0)k+='['+n+']';if(n==='role')k+='[role='+e.getAttribute(n)+']'}m[k]=(m[k]||0)+1});return Object.keys(m).sort(function(a,b){return m[b]-m[a]}).slice(0,600).map(function(k){return m[k]+' '+k}).join('\\n')})()";
pub fn probeRun(ctx: *ctxz.Ctx) !u8 { if (ctx.args.rest.len != 1 or !nameOk(ctx.args.rest[0])) return error.BadJob; var live = try ctxz.openLive(ctx, false); defer live.close(); if (std.mem.eql(u8, ctx.args.rest[0], "chat-open")) { try ctxz.emit(ctx, "open one chat by hand in the window now (45 seconds)\n"); try std.Io.sleep(ctx.iozz, .fromMilliseconds(45000), .awake); } const reg = try lab.load(ctx.allo, ctx.iozz, ctx.cfg.labl_file_path); const nodes = try snap.axSnap(ctx.allo, live.conn); const text = try snap.pageText(ctx.allo, live.conn); const body = try prob.dump(ctx.allo, &reg, nodes, text, ctxz.nowMs(ctx)); const path = try std.fmt.allocPrint(ctx.allo, "{s}{c}probe{c}{s}.json", .{ ctx.stat, std.fs.path.sep, std.fs.path.sep, ctx.args.rest[0] }); try file.fileAtom(ctx.allo, ctx.iozz, path, body); const skel = snap.evalStr(ctx.allo, live.conn, SKEL) catch ""; const skpt = try std.fmt.allocPrint(ctx.allo, "{s}{c}probe{c}{s}-dom.txt", .{ ctx.stat, std.fs.path.sep, std.fs.path.sep, ctx.args.rest[0] }); try file.fileAtom(ctx.allo, ctx.iozz, skpt, skel); try ctxz.emitf(ctx, "probe saved: {s} ({d} nodes, personal text hashed)\n", .{ path, nodes.len }); return 0; }
